/**
 * Konfigurasi Resi dari server (juragan.juragan.doctype.resi.resi.get_resi_config).
 *
 * Semua aturan tampilan & alur — susunan field, label, opsi, warna status,
 * tombol yang boleh muncul, dan hak ubah — dihitung di server dari meta doctype
 * dan konstanta alur Python. Halaman Vue hanya merender apa yang dikirim, jadi
 * perubahan di desk (menambah field, mengubah label, mengunci field, mengubah
 * alur) langsung ikut di aplikasi tanpa mengubah kode di sini.
 */

const ENDPOINT = '/api/method/juragan.juragan.doctype.resi.resi.get_resi_config'

/**
 * Ambil konfigurasi. Tanpa `docname` hanya bagian doctype (status, layout);
 * dengan `docname` ikut hak ubah dan daftar tombol untuk dokumen tersebut.
 */
export async function ambilKonfigurasiResi(docname) {
	const url = docname ? `${ENDPOINT}?docname=${encodeURIComponent(docname)}` : ENDPOINT
	const res = await fetch(url, {
		method: 'GET',
		credentials: 'include',
		headers: { Accept: 'application/json' },
	})
	const json = await res.json().catch(() => ({}))
	if (!res.ok) throw new Error(json?.exception || json?.message || `HTTP ${res.status}`)
	return json.message || {}
}

// Daftar status jarang berubah dan dipakai tiap baris list → cukup sekali ambil
// per sesi halaman.
let cacheStatus = null
export async function ambilStatusResi() {
	if (!cacheStatus) {
		const konfigurasi = await ambilKonfigurasiResi()
		cacheStatus = konfigurasi.statuses || []
	}
	return cacheStatus
}

/** Nama warna Frappe untuk satu status, sesuai Document States doctype. */
export function warnaStatus(statuses, value) {
	const status = (statuses || []).find((s) => s.value === value)
	return status?.color || 'gray'
}

// Warna Frappe → kelas Tailwind. Dipakai badge list dan banner detail.
const PILL = {
	gray: 'bg-ui-surface-gray-200 text-ui-ink-gray-700',
	grey: 'bg-ui-surface-gray-200 text-ui-ink-gray-700',
	darkgrey: 'bg-ui-surface-gray-300 text-ui-ink-gray-800',
	blue: 'bg-ui-surface-blue-100 text-ui-ink-blue-700',
	'light-blue': 'bg-ui-surface-sky-100 text-ui-ink-sky-700',
	cyan: 'bg-ui-surface-cyan-100 text-ui-ink-cyan-700',
	green: 'bg-ui-surface-green-100 text-ui-ink-green-700',
	orange: 'bg-ui-surface-orange-100 text-ui-ink-orange-700',
	yellow: 'bg-ui-surface-yellow-100 text-ui-ink-yellow-800',
	red: 'bg-ui-surface-red-100 text-ui-ink-red-700',
	pink: 'bg-ui-surface-pink-100 text-ui-ink-pink-700',
	purple: 'bg-ui-surface-purple-100 text-ui-ink-purple-700',
}

const BANNER = {
	gray: 'border-ui-line-gray-200 bg-ui-surface-gray-50 text-ui-ink-gray-700',
	grey: 'border-ui-line-gray-200 bg-ui-surface-gray-50 text-ui-ink-gray-700',
	darkgrey: 'border-ui-line-gray-300 bg-ui-surface-gray-100 text-ui-ink-gray-800',
	blue: 'border-ui-line-blue-200 bg-ui-surface-blue-50 text-ui-ink-blue-800',
	'light-blue': 'border-ui-line-sky-200 bg-ui-surface-sky-50 text-ui-ink-sky-800',
	cyan: 'border-ui-line-cyan-200 bg-ui-surface-cyan-50 text-ui-ink-cyan-800',
	green: 'border-ui-line-green-200 bg-ui-surface-green-50 text-ui-ink-green-800',
	orange: 'border-ui-line-orange-200 bg-ui-surface-orange-50 text-ui-ink-orange-800',
	yellow: 'border-ui-line-yellow-200 bg-ui-surface-yellow-50 text-ui-ink-yellow-800',
	red: 'border-ui-line-red-200 bg-ui-surface-red-50 text-ui-ink-red-800',
	pink: 'border-ui-line-pink-200 bg-ui-surface-pink-50 text-ui-ink-pink-800',
	purple: 'border-ui-line-purple-200 bg-ui-surface-purple-50 text-ui-ink-purple-800',
}

export function kelasPill(warna) {
	return PILL[warna] || PILL.gray
}

export function kelasBanner(warna) {
	return BANNER[warna] || BANNER.gray
}
